<template>
  <section class="page">
    <template v-if="isDashboard">
      <header class="dashboard-head">
        <div><small>EXAM & RESULTS</small><h1>Exam Dashboard</h1><p>পরীক্ষা, উপস্থিতি ও ফলাফলের বর্তমান সারসংক্ষেপ।</p></div>
        <div class="quick-actions"><RouterLink class="secondary-link" to="/exams/setup">Exam Setup</RouterLink><RouterLink class="primary-link" to="/exams/routine">Routine & Seating</RouterLink></div>
      </header>
      <p v-if="dashboardError" class="error">{{ dashboardError }}</p>

      <section class="metric-grid">
        <article class="metric indigo"><span class="metric-kicker">TOTAL EXAMS</span><strong>{{ number(summary.total_exams) }}</strong><small>{{ number(summary.scheduled_exams) }} scheduled · {{ number(summary.draft_exams) }} draft</small></article>
        <article class="metric blue"><span class="metric-kicker">EXAM CANDIDATES</span><strong>{{ number(summary.total_candidates) }}</strong><small>{{ number(summary.attended_students) }} students attended at least one exam</small></article>
        <article class="metric emerald"><span class="metric-kicker">ATTENDANCE</span><strong>{{ attendanceRate }}%</strong><small>{{ number(summary.attended_entries) }} attended · {{ number(summary.absent_entries) }} absent</small></article>
        <article class="metric rose"><span class="metric-kicker">RESULT STATUS</span><strong>{{ passRate }}%</strong><small>{{ number(summary.passed) }} pass · {{ number(summary.failed) }} fail · {{ number(summary.pending) }} pending</small></article>
      </section>

      <section class="dashboard-grid">
        <article class="panel attendance-panel">
          <div class="panel-head"><div><small>ATTENDANCE SNAPSHOT</small><h2>Exam attendance</h2></div><span class="percent">{{ attendanceRate }}%</span></div>
          <div class="progress"><span :style="{ width: `${attendanceRate}%` }"></span></div>
          <div class="legend"><div><i class="dot attended"></i><span>Attended</span><b>{{ number(summary.attended_entries) }}</b></div><div><i class="dot absent"></i><span>Absent</span><b>{{ number(summary.absent_entries) }}</b></div><div><i class="dot muted"></i><span>Recorded entries</span><b>{{ number(summary.recorded_entries) }}</b></div></div>
          <p class="panel-note">Attendance is calculated from marks-entry records. Existing inactive subject records remain visible as history.</p>
        </article>
        <article class="panel result-panel">
          <div class="panel-head"><div><small>RESULT SUMMARY</small><h2>Pass / Fail</h2></div><span class="percent">{{ passRate }}%</span></div>
          <div class="result-bars"><div><span>Pass</span><div><i class="pass" :style="{ width: `${resultPortion('passed')}%` }"></i></div><b>{{ number(summary.passed) }}</b></div><div><span>Fail</span><div><i class="fail" :style="{ width: `${resultPortion('failed')}%` }"></i></div><b>{{ number(summary.failed) }}</b></div><div><span>Pending</span><div><i class="pending" :style="{ width: `${resultPortion('pending')}%` }"></i></div><b>{{ number(summary.pending) }}</b></div></div>
        </article>
      </section>

      <article class="panel recent-panel">
        <div class="panel-head"><div><small>RECENT EXAMS</small><h2>Exam progress overview</h2></div><RouterLink to="/exams/setup">Manage exams →</RouterLink></div>
        <div class="table-wrap"><table><thead><tr><th>Exam</th><th>Class</th><th>Schedule</th><th>Candidates</th><th>Pass / Fail</th><th>Status</th></tr></thead><tbody>
          <tr v-for="exam in recentExams" :key="exam.exam_id"><td><b>{{ exam.exam_name }}</b><small>{{ exam.exam_type_name || 'General examination' }}</small></td><td>{{ exam.class_name || 'All classes' }}</td><td>{{ displayDate(exam.start_date) }}<small v-if="exam.end_date">to {{ displayDate(exam.end_date) }}</small></td><td>{{ number(exam.candidate_count) }}</td><td><span class="pass-text">{{ number(exam.passed_count) }} pass</span><span class="separator">/</span><span class="fail-text">{{ number(exam.failed_count) }} fail</span></td><td><span class="status" :class="String(exam.exam_status || 'DRAFT').toLowerCase()">{{ exam.exam_status }}</span></td></tr>
          <tr v-if="!recentExams.length"><td colspan="6" class="empty">No exam data available yet. Create an exam from Exam Setup.</td></tr>
        </tbody></table></div>
      </article>
    </template>

    <template v-else>
      <header><div><small>EXAM SETUP</small><h1>Exam Setup</h1><p>Exam ও subject list থেকে add, edit ও delete করুন।</p></div><button @click="openExam()">+ Add Exam</button></header>
      <p v-if="msg" :class="kind">{{ msg }}</p>
      <div class="layout"><aside><h2>Exams</h2><button v-for="x in exams" :key="x.exam_id" class="exam" :class="{ selected: current?.exam_id === x.exam_id }" @click="pickExam(x)">{{ x.exam_name }}<small>{{ x.class_name || 'All classes' }} · {{ x.exam_status }}</small></button><p v-if="!exams.length" class="empty">No exams created.</p></aside><main><div class="toolbar"><h2>{{ current?.exam_name || 'Select an exam' }}</h2><div v-if="current"><button class="secondary" @click="openExam(current)">Edit Exam</button><button @click="openSubject()">+ Add Subject</button></div></div><article v-if="current" class="subject-table"><div class="table-wrap"><table><thead><tr><th>Subject</th><th>Marks</th><th>Routine</th><th>Room</th><th>Action</th></tr></thead><tbody><tr v-for="x in subjects" :key="x.exam_subject_id"><td><b>{{ x.subject_name }}</b><small>{{ x.subject_code }}</small></td><td>{{ x.full_marks }} / Pass {{ x.pass_marks }}</td><td>{{ x.exam_date || '—' }}<small>{{ x.start_time || '—' }} – {{ x.end_time || '—' }}</small></td><td>{{ x.room_no || '—' }}</td><td><button class="mini" @click="openSubject(x)">Edit</button><button class="mini danger" @click="deleteSubject(x)">Delete</button></td></tr><tr v-if="!subjects.length"><td colspan="5" class="empty">No subject added.</td></tr></tbody></table></div></article></main></div>

      <div v-if="examModal" class="backdrop"><form class="modal" @submit.prevent="saveExam"><div class="modal-head"><h2>{{ examId ? 'Update' : 'Add' }} Exam</h2><button type="button" class="close" @click="examModal = false">×</button></div><div class="fields"><label>Exam Name<input v-model.trim="ef.exam_name" required /></label><BaseSelect v-model="ef.branch_id" label="Branch" :options="branchOptions" placeholder="Select branch" required /><BaseSelect v-model="ef.academic_year_id" label="Academic Year" :options="yearOptions" placeholder="Select year" required /><BaseSelect v-model="ef.exam_type_id" label="Exam Type" :options="typeOptions" placeholder="Select type" required /><BaseSelect v-model="ef.class_id" label="Class" :options="classOptions" placeholder="All classes" /><label>Start Date<input v-model="ef.start_date" type="date" /></label><label>End Date<input v-model="ef.end_date" type="date" /></label></div><div class="actions"><button>Save Exam</button><button type="button" class="secondary" @click="examModal = false">Cancel</button></div></form></div>
      <div v-if="subjectModal" class="backdrop"><form class="modal" @submit.prevent="saveSubject"><div class="modal-head"><h2>{{ subjectId ? 'Update' : 'Add' }} Subject</h2><button type="button" class="close" @click="subjectModal = false">×</button></div><div class="fields"><BaseSelect v-model="sf.subject_id" label="Subject" :options="subjectOptions" placeholder="Select subject" :disabled="Boolean(subjectId)" required /><label>Full Marks<input v-model.number="sf.full_marks" type="number" min="1" /></label><label>Pass Marks<input v-model.number="sf.pass_marks" type="number" min="0" /></label><label>Exam Date<input v-model="sf.exam_date" type="date" /></label><label>Start Time<input v-model="sf.start_time" type="time" /></label><label>End Time<input v-model="sf.end_time" type="time" /></label><label>Room<input v-model.trim="sf.room_no" /></label></div><div class="actions"><button>Save Subject</button><button type="button" class="secondary" @click="subjectModal = false">Cancel</button></div></form></div>
    </template>
  </section>
</template>

<script setup>
import { computed, onMounted, reactive, ref, watch } from 'vue';
import { useRoute } from 'vue-router';
import api from '../../services/api';
import { confirmAction, notify } from '../../services/notification';
import { withPreservedScroll } from '../../utils/preserveScroll';
import BaseSelect from '../../components/common/BaseSelect.vue';

const route = useRoute();
const isDashboard = computed(() => route.meta.examSection === 'dashboard' || route.path === '/exams');
const l = reactive({ branches: [], years: [], types: [], classes: [], subjects: [] });
const exams = ref([]), subjects = ref([]), current = ref(null), examId = ref(''), subjectId = ref(''), examModal = ref(false), subjectModal = ref(false), msg = ref(''), kind = ref('success');
const summary = ref({}), recentExams = ref([]), dashboardError = ref('');
const ef = reactive({ exam_name: '', branch_id: '', academic_year_id: '', exam_type_id: '', class_id: '', start_date: '', end_date: '' });
const sf = reactive({ subject_id: '', full_marks: 100, pass_marks: 33, exam_date: '', start_time: '', end_time: '', room_no: '' });
const branchOptions = computed(() => l.branches.map((x) => ({ value: x.branch_id, label: x.branch_name })));
const yearOptions = computed(() => l.years.map((x) => ({ value: x.academic_year_id, label: x.year_name })));
const typeOptions = computed(() => l.types.map((x) => ({ value: x.exam_type_id, label: x.exam_type_name })));
const classOptions = computed(() => l.classes.map((x) => ({ value: x.class_id, label: x.class_name })));
const subjectOptions = computed(() => l.subjects.map((x) => ({ value: x.subject_id, label: `${x.subject_code || ''} ${x.subject_name}`.trim() })));
const number = (value) => Number(value || 0);
const attendanceRate = computed(() => { const total = number(summary.value.attended_entries) + number(summary.value.absent_entries); return total ? Math.round((number(summary.value.attended_entries) / total) * 100) : 0; });
const passRate = computed(() => { const total = number(summary.value.total_results); return total ? Math.round((number(summary.value.passed) / total) * 100) : 0; });
const resultPortion = (key) => { const total = number(summary.value.total_results); return total ? Math.round((number(summary.value[key]) / total) * 100) : 0; };
const note = (text, type = 'success') => { msg.value = text; kind.value = type; };
const displayDate = (value) => { if (!value) return '—'; const raw = String(value); if (/^\d{2}-[A-Z]{3}-\d{4}$/i.test(raw)) return raw.toUpperCase(); const parsed = new Date(`${raw.slice(0, 10)}T00:00:00`); return Number.isNaN(parsed.getTime()) ? raw : new Intl.DateTimeFormat('en-GB', { day: '2-digit', month: 'short', year: 'numeric' }).format(parsed).toUpperCase(); };
const toInputDate = (value) => { const raw = String(value || ''); const match = raw.match(/^(\d{2})-([A-Z]{3})-(\d{4})$/i); if (match) { const month = ['JAN','FEB','MAR','APR','MAY','JUN','JUL','AUG','SEP','OCT','NOV','DEC'].indexOf(match[2].toUpperCase()) + 1; return `${match[3]}-${String(month).padStart(2, '0')}-${match[1]}`; } return raw.slice(0, 10); };
function resetExam() { examId.value = ''; Object.assign(ef, { exam_name: '', branch_id: '', academic_year_id: '', exam_type_id: '', class_id: '', start_date: '', end_date: '' }); }
function resetSubject() { subjectId.value = ''; Object.assign(sf, { subject_id: '', full_marks: 100, pass_marks: 33, exam_date: '', start_time: '', end_time: '', room_no: '' }); }
async function loadSetup() { const [lookups, examRows] = await Promise.all([api.get('/exams/lookups'), api.get('/exams/exams')]); Object.assign(l, lookups.data.data); exams.value = examRows.data.data || []; }
async function loadDashboard() { try { dashboardError.value = ''; const response = await api.get('/exams/dashboard/overview'); summary.value = response.data.data?.summary || {}; recentExams.value = response.data.data?.recent_exams || []; } catch (error) { dashboardError.value = error.response?.data?.message || 'Failed to load exam dashboard.'; } }
async function pickExam(exam) { current.value = exam; examId.value = exam.exam_id; subjects.value = (await api.get(`/exams/exams/${exam.exam_id}/subjects`)).data.data || []; }
function openExam(exam) { if (exam) { examId.value = exam.exam_id; Object.assign(ef, { ...exam, start_date: toInputDate(exam.start_date), end_date: toInputDate(exam.end_date) }); } else resetExam(); examModal.value = true; }
function openSubject(subject) { if (subject) { subjectId.value = subject.exam_subject_id; Object.assign(sf, { ...subject, exam_date: toInputDate(subject.exam_date), start_time: String(subject.start_time || '').slice(0, 5), end_time: String(subject.end_time || '').slice(0, 5) }); } else resetSubject(); subjectModal.value = true; }
async function saveExam() { try { const response = examId.value ? await api.put(`/exams/exams/${examId.value}`, ef) : await api.post('/exams/exams', ef); examModal.value = false; await loadSetup(); note('Exam saved.'); if (!current.value) await pickExam(response.data.data); } catch (error) { note(error.response?.data?.message || 'Save failed.', 'error'); } }
async function saveSubject() { try { if (subjectId.value) await api.put(`/exams/exam-subjects/${subjectId.value}`, sf); else await api.post(`/exams/exams/${current.value.exam_id}/subjects`, sf); subjectModal.value = false; await pickExam(current.value); note('Subject saved.'); } catch (error) { note(error.response?.data?.message || 'Save failed.', 'error'); } }
async function deleteSubject(subject) { if (!await confirmAction({ title: 'Delete exam subject?', message: `“${subject.subject_name}” will be removed from this exam.`, confirmText: 'Delete subject' })) return; try { await api.delete(`/exams/exam-subjects/${subject.exam_subject_id}`); await withPreservedScroll(() => pickExam(current.value)); note('Subject deleted.'); notify.success('Exam subject deleted.'); } catch (error) { note(error.response?.data?.message || 'Delete failed.', 'error'); notify.error(msg.value); } }
onMounted(() => isDashboard.value ? loadDashboard() : loadSetup().catch(() => note('Setup load failed.', 'error')));
watch(isDashboard, (dashboard) => { if (dashboard) loadDashboard(); else loadSetup().catch(() => note('Setup load failed.', 'error')); });
</script>

